func ttRect(b *port.Bitmap, x0 int32, y0 int32, x1 int32, y1 int32) int32 {
	// Ink in [x0, x1) x [y0, y1).
	var x int32 = 0
	var y int32 = y0
	for y < y1 {
		x = x0
		for x < x1 {
			if ((x >= 0) && (x < port.BitmapW(b))) && ((y >= 0) && (y < port.BitmapH(b))) {
				port.BitmapSetU8(b, x, y, 0, 255)
			}
			x += 1
		}
		y += 1
	}
	return 0
}

func ttDot(b *port.Bitmap, x int32, y int32) int32 {
	ttRect(b, x, y, x+1, y+1)
	return 0
}

func ttDisc(b *port.Bitmap, cx int32, cy int32, r2out int32, r2in int32) int32 {
	// Ink where r2in <= squared distance from (cx, cy) < r2out (a disc or a ring).
	var x int32 = 0
	var y int32 = 0
	var d int32 = 0
	for y < port.BitmapH(b) {
		x = 0
		for x < port.BitmapW(b) {
			d = ((x - cx) * (x - cx)) + ((y - cy) * (y - cy))
			if (d < r2out) && (d >= r2in) {
				port.BitmapSetU8(b, x, y, 0, 255)
			}
			x += 1
		}
		y += 1
	}
	return 0
}

func ttEllipse(b *port.Bitmap, cx int32, cy int32, rx int32, ry int32) int32 {
	var x int32 = 0
	var y int32 = 0
	for y < port.BitmapH(b) {
		x = 0
		for x < port.BitmapW(b) {
			if ((((x - cx) * (x - cx)) * (ry * ry)) + (((y - cy) * (y - cy)) * (rx * rx))) <= ((rx * rx) * (ry * ry)) {
				port.BitmapSetU8(b, x, y, 0, 255)
			}
			x += 1
		}
		y += 1
	}
	return 0
}

func ttLine(b *port.Bitmap, x0 int32, y0 int32, x1 int32, y1 int32, thick int32) int32 {
	// A line of the given thickness (vertical extent), x stepping, y by integer interpolation (|slope| <= 1).
	var x int32 = x0
	var y int32 = 0
	var j int32 = 0
	for x <= x1 {
		y = y0 + (((y1 - y0) * (x - x0)) / (x1 - x0))
		j = 0
		for j < thick {
			ttDot(b, x, y+j)
			j += 1
		}
		x += 1
	}
	return 0
}

