func ttField(b *port.Bitmap) int32 {
	// Fifty glyph blocks (6 x 8) in five rows at the bottom of the bitmap: the page's body text, which makes the median glyph 8 px so that
	// anything over 32 px is large.
	var y0 int32 = port.BitmapH(b) - 60
	var r int32 = 0
	var k int32 = 0
	for r < 5 {
		k = 0
		for k < 10 {
			ttRect(b, 2+(k*10), y0+(r*12), 8+(k*10), (y0+(r*12))+8)
			k += 1
		}
		r += 1
	}
	return 0
}

func ttNear(got int32, want int32, tol int32) int32 {
	var d int32 = got - want
	if d < 0 {
		d = 0 - d
	}
	if d <= tol {
		return 1
	}
	return 0
}

