func TestNoiseGlyphsRulesAndLargeThingsAreToldApart(emonT *testing.T) {
	var b *port.Bitmap = port.BitmapNew(200, 160, 1)
	var comps *port.Cells = port.NewCells()
	var rules *port.Cells = port.NewCells()
	var prims *port.Cells = port.NewCells()
	var tlines *port.Cells = port.NewCells()
	var pts *port.Cells = port.NewCells()
	var refs *port.Cells = port.NewCells()
	var views *port.Cells = port.NewCells()
	var inks *port.Cells = port.NewCells()
	var i int32 = 0
	var r int32 = 0
	// thirty glyph-sized blocks in three rows, a speck, a tall thin bar (a rule), a long thin one, and a big block
	for r < 3 {
		i = 0
		for i < 10 {
			ttRect(b, 4+(i*10), 4+(r*12), 10+(i*10), 12+(r*12))
			i += 1
		}
		r += 1
	}
	ttDot(b, 190, 5)
	ttRect(b, 170, 60, 172, 90)
	ttRect(b, 4, 100, 150, 102)
	ttRect(b, 4, 110, 60, 148)
	ttTrace(b, 7200, comps, rules, prims, tlines, pts, refs, views, inks)
	port.AssertEq(emonT, evidence.CoCount(comps), 34, "thirty-four components")
	port.AssertEq(emonT, evidence.CoGet(comps, 0, evidence.CfKind()), evidence.CkTextLike(), "a glyph-sized block is text-like")
	port.AssertEq(emonT, evidence.CoGet(comps, 0, evidence.CfConf()), 900, "with confidence 900")
	// sorted by top: the first row (y 4), the speck (y 5), the second and third rows, the tall bar, the long bar, the big block
	port.AssertEq(emonT, evidence.CoGet(comps, 10, evidence.CfKind()), evidence.CkBlob(), "the speck is blob (noise)")
	port.AssertEq(emonT, evidence.CoGet(comps, 10, evidence.CfConf()), 0, "with confidence 0")
	port.AssertEq(emonT, evidence.CoGet(comps, 31, evidence.CfKind()), evidence.CkRuleV(), "the tall thin bar is a vertical rule")
	port.AssertEq(emonT, evidence.CoGet(comps, 32, evidence.CfKind()), evidence.CkRuleH(), "the long thin one is a horizontal rule")
	port.AssertEq(emonT, evidence.CoGet(comps, 33, evidence.CfKind()), evidence.CkBlob(), "the big block is large (blob)")
	port.AssertEq(emonT, evidence.CoGet(comps, 33, evidence.CfConf()), 700, "with confidence 700")
}

