func TestDouglasPeuckerDropsAStaircaseAndKeepsACorner(emonT *testing.T) {
	var raw *port.Cells = port.NewCells()
	var keep *port.Cells = port.NewCells()
	var stk *port.Cells = port.NewCells()
	// an open chain along a gentle line with one-pixel wobble, then a real corner
	port.CellsPush(raw, 0)
	port.CellsPush(raw, 0)
	port.CellsPush(raw, 5)
	port.CellsPush(raw, 1)
	port.CellsPush(raw, 10)
	port.CellsPush(raw, 0)
	port.CellsPush(raw, 15)
	port.CellsPush(raw, 1)
	port.CellsPush(raw, 20)
	port.CellsPush(raw, 0)
	port.AssertEq(emonT, trace.TrSimplify(raw, 5, 0, 9, keep, stk), 2, "the wobble is under 1.5 px: only the ends stay")
	port.CellsPush(raw, 20)
	port.CellsPush(raw, 20)
	port.AssertEq(emonT, trace.TrSimplify(raw, 6, 0, 9, keep, stk), 3, "a corner 20 px off the chord stays")
	port.AssertEq(emonT, port.CellsAt(keep, 5), 1, "the end")
	var sq *port.Cells = port.NewCells()
	port.CellsPush(sq, 0)
	port.CellsPush(sq, 0)
	port.CellsPush(sq, 10)
	port.CellsPush(sq, 0)
	port.CellsPush(sq, 10)
	port.CellsPush(sq, 10)
	port.CellsPush(sq, 0)
	port.CellsPush(sq, 10)
	port.AssertEq(emonT, trace.TrSimplify(sq, 4, 1, 9, keep, stk), 4, "a closed square keeps its four corners")
}

