func ttGlyphs(b *port.Bitmap, x0 int32, y0 int32, n int32, dx int32, dy int32) int32 {
	// n glyph blocks of 8 x 10 pixels, the k-th at (x0 + k dx, y0 + k dy), each a box with a small notch.
	var k int32 = 0
	for k < n {
		ttRect(b, x0+(k*dx), y0+(k*dy), (x0+(k*dx))+8, (y0+(k*dy))+10)
		k += 1
	}
	return 0
}

